// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
    const cols = line.split(",").map(c => c.trim());
    const obj = {};
    headers.forEach((h, i) => obj[h] = cols[i] ?? "");

    // normaliza minimo para número
    obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

    return obj;
});

return [{ json: { investimentos } }];

// Acessa o primeiro item recebido no n8n
const inputItem = $input.first();

// Extrai a lista de clientes de dentro do body
const clientes = inputItem.json.body.clientes;

// Array para armazenar as mensagens geradas
const mensagensGeradas = [];

// Função para formatar a moeda (caso venha como string ou número)
function formatarSaldo(saldo) {
    if (typeof saldo === 'number') {
        return saldo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    }
    return saldo; // Retorna a string original se já vier formatada (ex: "R$ 12.500,00")
}

// Processa cada cliente
clientes.forEach((cliente, index) => {
    let assunto = "";
    let corpo = "";
    const saldoFormatado = formatarSaldo(cliente.saldo);
    const perfilLower = cliente.perfil ? cliente.perfil.toLowerCase() : "";

    switch (perfilLower) {
        case "conservador":
            assunto = `Seu patrimônio protegido e rendendo com segurança, ${cliente.nome}!`;
            corpo = `Olá, ${cliente.nome}! Com seus ${saldoFormatado}, sabemos que a prioridade é a segurança. Preparamos opções em Renda Fixa com liquidez diária e proteção do FGC.`;
            break;

        case "moderado":
            assunto = `Equilíbrio ideal para fazer seu dinheiro render mais, ${cliente.nome}!`;
            corpo = `Olá, ${cliente.nome}! Seus ${saldoFormatado} têm um potencial excelente. Conseguimos combinar a segurança da renda fixa com fundos multimercados.`;
            break;

        case "arrojado":
            assunto = `Oportunidades de alto potencial para o seu capital, ${cliente.nome}!`;
            corpo = `Olá, ${cliente.nome}! Com um saldo de ${saldoFormatado} e seu perfil arrojado, o momento é ideal para diversificar em ativos de maior volatilidade.`;
            break;

        default:
            assunto = `Novidades para os seus investimentos, ${cliente.nome}!`;
            corpo = `Olá, ${cliente.nome}! Temos opções especiais para os seus ${saldoFormatado}.`;
    }

    // Adiciona o resultado formatado para o próximo nó do n8n consumir individualmente
    mensagensGeradas.push({
        json: {
            id: index + 1,
            nome: cliente.nome,
            email: cliente.email,
            saldo: saldoFormatado,
            perfil: cliente.perfil,
            assunto: assunto,
            mensagem: corpo
        }
    });
});

return mensagensGeradas;

