// Pega todos os itens que vieram do nó da LLM
const itens = $input.all();

const mensagensFormatadas = itens.map((item, index) => {
    // Tenta extrair o texto JSON gerado pela IA
    const outputObj = item.json.output?.[0] || item.json;
    const contentItem = outputObj.content?.[0];
    const textoBruto = contentItem?.text || JSON.stringify(item.json);

    let dadosEmail;
    try {
        // Limpa possíveis marcações de bloco de código markdown que a IA possa incluir
        let jsonLimpo = textoBruto.replace(/```json/g, "").replace(/```/g, "").trim();
        dadosEmail = JSON.parse(jsonLimpo);
    } catch (error) {
        dadosEmail = {
            subject: "Atualização sobre seus Investimentos",
            text_body: textoBruto,
            html_body: `<p>${textoBruto}</p>`
        };
    }

    // Lista fixa de e-mails correspondentes à ordem dos clientes processados anteriormente
    const emailsClientes = [
        "ana@email.com",     // 1. Ana Silva
        "bruno@email.com",    // 2. Bruno Lima
        "carla@email.com",    // 3. Carla Souza
        "daniel@email.com",   // 4. Daniel Oliveira
        "elena@email.com",    // 5. Elena Rodrigues
        "felipe@email.com",   // 6. Felipe Santos
        "gabriela@email.com", // 7. Gabriela Costa
        "henrique@email.com", // 8. Henrique Alves
        "isabela@email.com",  // 9. Isabela Martins
        "joao@email.com"      // 10. João Pereira
    ];

    // Define o e-mail com base na posição (index) do item
    const emailDestino = emailsClientes[index] || "cliente@email.com";

    return {
        json: {
            to: emailDestino,                               // Campo exato para o nó de e-mail do n8n
            subject: dadosEmail.subject || "Oportunidades de Investimento", // Assunto padronizado
            text: dadosEmail.text_body || "",                 // Versão texto plano
            html: dadosEmail.html_body || ""                  // Versão HTML formatada
        }
    };
});

return mensagensFormatadas;
